const VOICE_DATA = {"file":"voice/ep12.mp3","lines":{"ep12_001":{"who":"TAKUTO","text":"Previously. Tyr the Frost Titan cracked the golden wall over Saint Lumen.","mono":false,"off":0.25,"dur":4.523,"env":"0117775257984431233211000000328998292111898864442022256641023333001157652000421367653255454578876433332232432443112454322110000000000000"},"ep12_002":{"who":"TAKUTO","text":"I opened the door. Akuro killed the Titan, and then turned on the city.","mono":false,"off":5.1727,"dur":4.715,"env":"0004541179810455444126666532100000000000000027984001155447675310113755311311322554310122211013444444422413544442443333234434431210000000000000"},"ep12_003":{"who":"TAKUTO","text":"Nemu stood in front of me and spent her eighth life. I came back.","mono":false,"off":10.2873,"dur":4.181,"env":"013568877777764552169645531137655423433333342540056531356200555310102478842100000000000000003651114655554377642100000000000000"},"ep12_004":{"who":"TAKUTO","text":"And the Saint decided that to mend his wall, he would take every Brand in the city.","mono":false,"off":14.8687,"dur":4.864,"env":"00157755436988631015443368876635421155520224556555554543212589986322100000000002757611427972010057851465311576556554343333233326531210000000000000"},"ep12_005":{"who":"LUCIEN","text":"Light of the city. Come home to the wall.","mono":false,"off":20.1327,"dur":2.283,"env":"268977613622354433776354321000025865532586655522426533576665332210000"},"ep12_006":{"who":"LUCIEN","text":"Great Sanctum. Close.","mono":false,"off":22.8153,"dur":1.621,"env":"0237987630232297655200265343303158876432222210000"},"ep12_007":{"who":"CROWD2","text":"Mama? Mama, I feel cold.","mono":false,"off":24.8367,"dur":1.984,"env":"035988866766422336666534553365301455301126544323212100000000"},"ep12_008":{"who":"WICK","text":"My fire. Takuto, my fire is shrinking. It has never been this small.","mono":false,"off":27.2207,"dur":3.861,"env":"04666102987666641136962118513787655655300487655555433323665213211100000054754368775276326665554444415443321110000000"},"ep12_009":{"who":"RIN","text":"My threads are thin. Like hair. I can barely hold them.","mono":false,"off":31.482,"dur":2.987,"env":"027886122999538765211039887766665311135654332100001772238872797775664214775530143320000000"},"ep12_010":{"who":"NEMU","text":"Everything is spinning. Is the room spinning? Or is it me?","mono":false,"off":34.8687,"dur":4.117,"env":"0265125410045532143322300355321100000000000000000000001543116425899876544230056643322110000000000026643234323300355310000000"},"ep12_011":{"who":"TAKUTO","text":"Nemu, sit.","mono":false,"off":39.386,"dur":1.003,"env":"0146999889987444349631000000000"},"ep12_012":{"who":"NEMU","text":"I am sitting. I think. It is hard to tell.","mono":false,"off":40.7887,"dur":2.837,"env":"03698766442328724422000000000003796100677310100000000275654124676610421031343221000000"},"ep12_013":{"who":"HARUKI","text":"It is the Great Sanctum. It is drinking every Brand under the dome. All of them. At once.","mono":false,"off":44.026,"dur":4.757,"env":"05995456521842388763034335776640133111100000000007888753126966236641477337753168766665565554642677665433104777574325444330016411577531113332000"},"ep12_014":{"who":"RIN","text":"How long?","mono":false,"off":49.1833,"dur":0.768,"env":"015899889887655421100000"},"ep12_015":{"who":"HARUKI","text":"By sunset, every Brand in Saint Lumen is in the wall. Hunters. Children. Us.","mono":false,"off":50.3513,"dur":4.416,"env":"0977533486663358730047733765315766655555322665214676555544313545666655446666422110000000000697622566554310132787643554212432222220000"},"ep12_016":{"who":"TAKUTO","text":"And the axe?","mono":false,"off":55.1673,"dur":0.896,"env":"057978877899853001322100000"},"ep12_017":{"who":"AKURO","text":"It is pulling at me too, boy. Gently. Like a thief who thinks the house is asleep. I do not like it.","mono":true,"off":56.4633,"dur":7.467,"env":"02359764334432100013466556445644333454421122234664544521367776665444322111123567551122333332112454324520000134333332000135531014553322214533334765543222112532234223222122243210000000001233322554555565211234544321012210000000"},"ep12_018":{"who":"TAKUTO","text":"Akuro does not like it.","mono":false,"off":64.33,"dur":1.621,"env":"1476111486489876423544346554113554410121000000000"},"ep12_019":{"who":"HARUKI","text":"Then we have something in common with him. That is a first.","mono":false,"off":66.3513,"dur":2.923,"env":"0399766677777334376521655555532215777666555441254333321000017875654641005875322331010000"},"ep12_020":{"who":"VALENTINE","text":"Darlings. My Encore is a candle. Gideon's chains are getting lazy. Vesper's wind is a breeze. We have perhaps eight hours.","mono":false,"off":69.674,"dur":6.656,"env":"26999866545551204544325787611035433233110243332122110000001653566744205245455432320143333334445432222110000000000000019634103553211665653322410145543222112014223400012211463013104442113333221111121000"},"ep12_021":{"who":"SIEG","text":"Then we use them. Haruki. Where is the heart of the Sanctum?","mono":false,"off":76.73,"dur":3.776,"env":"087666766666656665303765555200000002987778776301186554300000000398766765137643776662275446543358776300254322210000"},"ep12_022":{"who":"HARUKI","text":"Under the cathedral. The crystal chamber, where the forty sleep. Lucien stands at the altar. He is the wall. As long as he wills it, it holds.","mono":false,"off":80.906,"dur":7.253,"env":"06886685461277300566534664321351137743015531331766553554346535300266645433313564200000000000000000379775335554330366655354126414666421244323226565430475445667653222000002654378755653265446655432542133222654311110221000"},"ep12_023":{"who":"GIDEON","text":"Then the boy strikes the altar.","mono":false,"off":88.5593,"dur":1.835,"env":"01599688752278886322111220167532002210244454310111100000"},"ep12_024":{"who":"HARUKI","text":"He cracked the Sanctum once. A hairline. Lucien was surprised. He will not be surprised again. His will is stronger than the barrier.","mono":false,"off":90.794,"dur":6.827,"env":"0076223887730005533676521656555653112322000000000166579986566443333000000002698763346556533352016765554443111464566666510454335101665555314424643322100007754448654235433101776554466355655316555543221100000"},"ep12_025":{"who":"TAKUTO","text":"Then I need him to stop willing it.","mono":false,"off":98.0207,"dur":1.941,"env":"00488888877787846765233465319999600024896554221100000000000"},"ep12_026":{"who":"HARUKI","text":"For three seconds.","mono":false,"off":100.362,"dur":1.323,"env":"0129984016576666532598413544333332210000"},"ep12_027":{"who":"TAKUTO","text":"...Frozen Hour.","mono":false,"off":102.0847,"dur":1.088,"env":"000139986445643145664321111000000"},"ep12_028":{"who":"HARUKI","text":"If I freeze the Saint himself, his will stops with him. Three seconds of a wall with nobody holding it.","mono":false,"off":103.5727,"dur":5.44,"env":"28359874101566665205532476532655332277654100004754435654332058775123126640242110000000000000138876543277205654644765456666655335512666664356354432565543432211000000"},"ep12_029":{"who":"SIEG","text":"You have to touch him to freeze him. Inside his own Sanctum. With Sable beside him.","mono":false,"off":109.4127,"dur":5.205,"env":"0799987520026403674114277664265200586566531664443100000000049986432575555548965666666643217766520165443100000000079523225866655665437533247665554244322110000"},"ep12_030":{"who":"HARUKI","text":"I know. I have touched him a thousand times. He always let me.","mono":false,"off":115.018,"dur":3.136,"env":"05999989877776411678853032972330287772068766545663358766543333310587788657765526873023321100000"},"ep12_031":{"who":"VESPER","text":"The Order has sealed every gate. Two hundred knights. They will not let a Branded near the cathedral.","mono":false,"off":118.554,"dur":5.291,"env":"045229998377423633322356555411029832465201675432002210004267743676436311677544310122210000000003774777888889413765620377665543421255554413111410044411233222000"},"ep12_032":{"who":"VALENTINE","text":"Then Gideon and I will give them a show at the cathedral doors. Encore, and every iron hinge in the building.","mono":false,"off":124.2447,"dur":5.717,"env":"0566760156134454444434444442232014300233324442444333200100121000333022321024332211124300000000000005999663111443210002431005631243204444333342003455423233332014332011111000"},"ep12_033":{"who":"GIDEON","text":"I have always wanted to make a cathedral door fight a knight.","mono":false,"off":130.362,"dur":3.307,"env":"0168973489985654323026763112202235430121113100034531133321144443210000165210000000000344543210000000"},"ep12_034":{"who":"VESPER","text":"I take the north gate. The knights there would like to keep the wounded out of the city. They are about to change their minds.","mono":false,"off":134.0687,"dur":6.443,"env":"05794031695201048987775301016654310021000000002899988720230066653463157764100231011452000176335899955624655442103322246523332310000000001788888831977510123114345555533026555566554333322212211000"},"ep12_035":{"who":"SIEG","text":"And I go with you. One sword. A frog crutch. Ha. Do not argue, Valentine.","mono":false,"off":140.9113,"dur":5.184,"env":"069877754496776677411687765200000005987776443387777653100047311287666643002297520145420000000000089776653159877555212577665367765458655676643276543332200000"},"ep12_036":{"who":"VALENTINE","text":"I was not going to argue. I was going to cry.","mono":false,"off":146.4953,"dur":2.837,"env":"04787686689988200288666443426666620133332000000467475317976541510114654332220000000000"},"ep12_037":{"who":"WICK","text":"Nemu and me. The Rite Hall. The people in the golden chairs. We carry them out before the wall eats them.","mono":false,"off":149.7327,"dur":5.461,"env":"04887788888887776766553018644999751215888653200430227830376777752277764256643434765431124420000000056122898878377777763002521176365456776642014530563032111000000000"},"ep12_038":{"who":"NEMU","text":"I can carry people. Slowly. On my tail.","mono":false,"off":155.594,"dur":3.179,"env":"025402277613146665401314102210000000000013441478876322110000000000000179776665530421433211000000"},"ep12_039":{"who":"RIN","text":"And I tie the way open. For you two. Into the crystal chamber, and back out.","mono":false,"off":159.1727,"dur":4.373,"env":"057899813335789839569988626985002544432000001486688604528976543200005864427112674512662145287777547664256624765301344332100100000000"},"ep12_040":{"who":"TAKUTO","text":"Rin. If the thread snaps...","mono":false,"off":163.946,"dur":1.664,"env":"02478987642241036100379973133305555321011210000000"},"ep12_041":{"who":"RIN","text":"Then Kaito's scarf still holds. You have it on your wrist.","mono":false,"off":166.01,"dur":3.115,"env":"0899952268898999744422788861133327876413786444211210000377456953867767666533775212221010000000"},"ep12_042":{"who":"SIEG","text":"Takuto. Last lesson. Always the first move.","mono":false,"off":169.5247,"dur":3.456,"env":"02987621198752287666666520000278866653304777533375443200000002787766666642574100876653007976544322110000"},"ep12_043":{"who":"TAKUTO","text":"Not this time. This time Haruki moves first.","mono":false,"off":173.3807,"dur":2.901,"env":"0246883006954202565543211101385410256555433566555411034445443311210027631001210000000000"},"ep12_044":{"who":"SIEG","text":"...Ha. Good. Now you are a teacher.","mono":false,"off":176.682,"dur":2.133,"env":"0148977775698877656300000299866677777667774133796315447443321000"},"ep12_045":{"who":"HUNTER","text":"Halt! By order of the Saint, no Branded may enter!","mono":false,"off":179.2153,"dur":3.541,"env":"00028998610000666534566345531122222143332100001233443110454333322211122221122320001111000000000000000000000"},"ep12_046":{"who":"CROWD","text":"Shields up! Shields up!","mono":false,"off":183.1567,"dur":1.877,"env":"011167877764369975100000111255444332125443210000000000000"},"ep12_047":{"who":"VALENTINE","text":"Ladies and gentlemen of the Gilded Order! Tonight, for one performance only!","mono":false,"off":185.434,"dur":4.373,"env":"036788623555354456315576623234433212200240015654215322244431222100000000000326789996410210045327977511320005654433136124544322111000"},"ep12_048":{"who":"VALENTINE","text":"Encore!","mono":false,"off":190.2073,"dur":0.96,"env":"07899888412166554332100000000"},"ep12_049":{"who":"GIDEON","text":"Cogwheel Core! Doors! Hinges! Candlesticks! Everyone, up!","mono":false,"off":191.5673,"dur":4.139,"env":"01699731366530112664322100000038875322111100000000498852223321100000015787523322210121001100000000158423443233322112221000000"},"ep12_050":{"who":"HUNTER","text":"The doors! The doors are fighting us!","mono":false,"off":196.106,"dur":2.645,"env":"00432299899986521014311565666542143210002666543222222222110000000000000000000000"},"ep12_051":{"who":"CROWD","text":"Why are we dancing? Why can't I stop dancing?","mono":false,"off":199.1513,"dur":2.923,"env":"0258998889756631276655224211110001466620111665444442441065442000054433223111100000000000"},"ep12_052":{"who":"GIDEON","text":"Go, boy! The stairs behind the altar! Go!","mono":false,"off":202.474,"dur":3.008,"env":"0399877531168764211000000234420677554322005323665434355663202121100000000000156643211000000"},"ep12_053":{"who":"TAKUTO","text":"Gideon. Valentine. Thank you.","mono":false,"off":205.882,"dur":1.899,"env":"027944445543321287644433133443322000055442011111000000000"},"ep12_054":{"who":"VALENTINE","text":"Thank us at the cast party, darling. GO!","mono":false,"off":208.1807,"dur":2.603,"env":"0049994375545105222467536100146665244420487776544334431000039975443210000000000"},"ep12_055":{"who":"HUNTER","text":"Executioner! The Guild has no authority in the holy city!","mono":false,"off":211.1833,"dur":4.011,"env":"0660123410169842224433322100321168876223453125566665641000466666542222211222220034322221111243312111000000000000000000000"},"ep12_056":{"who":"HUNTER","text":"Stand down!","mono":false,"off":215.594,"dur":1.152,"env":"00010079777776632147654332211110000"},"ep12_057":{"who":"VESPER","text":"The Guild has no authority. I have a great deal of wind. White Gale.","mono":false,"off":217.146,"dur":3.989,"env":"035139976521126332887665542000555544431322210045543561531137653100356454201466543333221000000035765300014544332222121000"},"ep12_058":{"who":"VESPER","text":"Open the gate, and let the wounded in. Or fly.","mono":false,"off":221.5353,"dur":2.795,"env":"068960036876304766531030156557730025333677753521444433332000355311114664432211110000"},"ep12_059":{"who":"SIEG","text":"Behind us. Ten knights. I can hold five. With the crutch, maybe four.","mono":false,"off":224.73,"dur":4.416,"env":"0897687666656664331000329766666556543023321000000048735888896666431047555555553100000005874752138752134138876665576531027654432210000"},"ep12_060":{"who":"KUROZANE","text":"Then I will hold the other six, Valen.","mono":false,"off":229.546,"dur":2.688,"env":"001488789998576311687664245435643542222255310011101114555432221111100000000000000"},"ep12_061":{"who":"SIEG","text":"Kurozane!","mono":false,"off":232.634,"dur":1.045,"env":"01299766776657766676554444200000"},"ep12_062":{"who":"KUROZANE","text":"I said after. This is after. If the Saint drinks your Brand, there is nothing left for me to kill.","mono":false,"off":234.0793,"dur":5.888,"env":"014665222498668776410003332211254111331223444310000211100000000002100322215554321014544111242104654433333321133332114444310243333343100000122222011000033322110000000000000000000"},"ep12_063":{"who":"SIEG","text":"Ha! That is the most romantic thing anyone has ever said to me.","mono":false,"off":240.3673,"dur":3.904,"env":"0199876654211677438874158887676300288776766555622630001876664200000000577776666568974100585565333487642125544332110000"},"ep12_064":{"who":"KUROZANE","text":"Do not make it strange, Valen. Fang Draw.","mono":false,"off":244.6713,"dur":3.093,"env":"001576799942665015102330147544444321111155554322221110000003543333311244443311100000000000000"},"ep12_065":{"who":"VESPER","text":"The gate is open! Bring the wounded through! Move!","mono":false,"off":248.1647,"dur":2.667,"env":"03620698651414443179950014443310007678774366664452001215654333455554333211100000"},"ep12_066":{"who":"SIEG","text":"Ha! Kurozane, behind you. Not that one. The OTHER one.","mono":false,"off":251.2313,"dur":3.52,"env":"0159765520126976766577666666545663265556765565541000068652004764200676554300000000395157657664454322210000"},"ep12_067":{"who":"KUROZANE","text":"Stop helping, Valen. You are bouncing.","mono":false,"off":255.1513,"dur":2.624,"env":"0011069960136760036343212666543332221000133432114433221111121111000000000000000"},"ep12_068":{"who":"SIEG","text":"Efficiently! Gideon says I bounce efficiently!","mono":false,"off":258.1753,"dur":2.944,"env":"28714975438752268776510000000696876665325765576676524765666522156200576432763024432110000"},"ep12_069":{"who":"HARUKI","text":"Takuto. The cat. Did you ever give it a name?","mono":false,"off":261.5193,"dur":2.581,"env":"238986113984437877654354123977752000046557725863675437744746666666542221100000"},"ep12_070":{"who":"TAKUTO","text":"Coffee.","mono":false,"off":264.5007,"dur":0.747,"env":"01379983112654321100000"},"ep12_071":{"who":"HARUKI","text":"You named the cat Coffee.","mono":false,"off":265.6473,"dur":1.579,"env":"026999887666754841269884102289874214433333200000"},"ep12_072":{"who":"TAKUTO","text":"It drank coffee milk. It made sense.","mono":false,"off":267.626,"dur":2.155,"env":"05311399764122599711344444332000000003555545203325542100121000000"},"ep12_073":{"who":"HARUKI","text":"Ha. I called it Mister Tuesday. Because I met it on a Tuesday.","mono":false,"off":270.1807,"dur":3.307,"env":"0017988775478621358775653466521563231977753045333320000017449669777667756567665131776643034221100000"},"ep12_074":{"who":"TAKUTO","text":"That is worse.","mono":false,"off":273.8873,"dur":0.981,"env":"004896785333379874211221000000"},"ep12_075":{"who":"HARUKI","text":"It is much worse. I am glad you never knew.","mono":false,"off":275.2687,"dur":2.411,"env":"0697875478851321478887643432016776664257877764347667773466656532111100000"},"ep12_076":{"who":"HARUKI","text":"If I do not come back up these stairs...","mono":false,"off":278.0793,"dur":2.155,"env":"07838988659888788420287764877631762026766433117776543222232200000"},"ep12_077":{"who":"TAKUTO","text":"You are coming back up.","mono":false,"off":280.634,"dur":1.28,"env":"013698402397676652677640145320000000000"},"ep12_078":{"who":"HARUKI","text":"If I do not, tell my mother I was trying to help people. Even when I was wrong. Especially then.","mono":false,"off":282.314,"dur":5.227,"env":"0782697864687777677410041885676677666537663256655402176664554675100015751033222000000488864776667666665655247877642211000000000566410897543355652554321100000"},"ep12_079":{"who":"TAKUTO","text":"Tell her yourself. That is the plan. Three seconds, then home for dinner.","mono":false,"off":287.9407,"dur":4.331,"env":"0238986786457974444388764200002566454320330110565553210000000000000012476544435962014443212544442255554421133215543210000000000000"},"ep12_080":{"who":"HARUKI","text":"...Three seconds. Then dinner.","mono":false,"off":292.6713,"dur":1.728,"env":"0122358766643269731465554325766663776554333222100000"},"ep12_081":{"who":"CROWD2","text":"Who... who is there? I cannot feel my hands.","mono":false,"off":294.7993,"dur":2.475,"env":"001999864313767853105755554238611154478610035533654212343332212222000000000"},"ep12_082":{"who":"WICK","text":"It is okay! We are Hunters! Rank F! Well, rank F with a lot of experience! We are getting you out!","mono":false,"off":297.674,"dur":5.035,"env":"07679659983024876664367776422866432544332003777650145753200000002687745766411267400442644776452430454004665544332142035564215664555544333331000000000000"},"ep12_083":{"who":"NEMU","text":"Arms around my neck. Hold the tail if you cannot hold me. It is a very strong tail.","mono":false,"off":303.1087,"dur":6.357,"env":"05688877654344232566654444443332210000100000000000000000000000199777114604115554432101311320324456432010015433010011000000000000000000000000265364324310055544432443402156555443131221111000000"},"ep12_084":{"who":"CROWD2","text":"Your head is on fire.","mono":false,"off":309.866,"dur":1.6,"env":"024998433689854453366643210397664434322100000000"},"ep12_085":{"who":"CROWD2","text":"It is so warm. Thank you. Thank you.","mono":false,"off":311.866,"dur":2.069,"env":"038979643348887424667787633210575411453104654211332210000000000"},"ep12_086":{"who":"WICK","text":"Everybody says that! It is my head! It is always on fire! You are welcome!","mono":false,"off":314.3353,"dur":4.075,"env":"059428851999677554698641088773004758653798777763565331000000668552289976886577763110887655443345566643666520213211100000000"},"ep12_087":{"who":"NEMU","text":"Wick. There are sixty chairs. We have carried eleven.","mono":false,"off":318.81,"dur":3.307,"env":"0089620001000477753322621220343043144332100023310000000000000000068821032566766523544456610321000000"},"ep12_088":{"who":"WICK","text":"Then we carry forty-nine more. Rank F does not stop. Rank F has nothing to lose.","mono":false,"off":322.5167,"dur":4.736,"env":"05989941259899951118983257777777788865533221000000498871226871002865368764145319887630000127877611247751115644577630455234544643221133200000000"},"ep12_089":{"who":"NEMU","text":"...You are very brave today.","mono":false,"off":327.6527,"dur":1.557,"env":"00068897211198766642004357655110641353211000000"},"ep12_090":{"who":"WICK","text":"I am terrified, Nemu. That is my brave face. Keep carrying.","mono":false,"off":329.61,"dur":3.456,"env":"05676672433888951079876535776667775544311377465447764217766631105432234321000147200116765432211110000000"},"ep12_091":{"who":"LUCIEN","text":"Haruki. You came home.","mono":false,"off":333.466,"dur":1.771,"env":"012698767874112276543211551126865553227766543222210000"},"ep12_092":{"who":"HARUKI","text":"This was never home, Lucien. It was a waiting room.","mono":false,"off":335.6367,"dur":2.773,"env":"028965148657989829964398776554568775334544330000463675786477776566555676542120000000"},"ep12_093":{"who":"LUCIEN","text":"Takuto. Look around you. Forty people, sleeping. A hundred thousand, alive. Do you know what holds the sky shut over this city?","mono":false,"off":338.81,"dur":7.083,"env":"028862129722378876443476126757765665233221000000000699856401176400333233236861033221000000002653797637731005865556532554245566665543222210000014787877746722177653221034333017654444233357522552352453322257523221000"},"ep12_094":{"who":"TAKUTO","text":"Them.","mono":false,"off":346.2927,"dur":0.597,"env":"002999755431000000"},"ep12_095":{"who":"LUCIEN","text":"Them. And me. For twelve years I have chosen who pays. Do you think that was easy?","mono":false,"off":347.29,"dur":4.267,"env":"02697655412466677664320000000046222197653123666554225555531033576532453344101155444322112200013563017430375301332124553223210000"},"ep12_096":{"who":"TAKUTO","text":"I think you liked choosing.","mono":false,"off":351.9567,"dur":1.429,"env":"0366401752166698520143255443232110100000000"},"ep12_097":{"who":"TAKUTO","text":"You do not get to choose who pays. Nobody does. Break the wall. Let them choose for themselves.","mono":false,"off":353.786,"dur":5.995,"env":"001352597788741059501331253355433243102135554321110111000000000246789257645323777643222210002776200045335799975322100000000037840165531443555433103323333232455432110001210000000000"},"ep12_098":{"who":"LUCIEN","text":"And when the Rift opens? When the sky eats this city the way it ate my village?","mono":false,"off":360.1807,"dur":4.224,"env":"0488798767646963102037872014322222210000000002887644405976665521564113202643222575354425545766562146751003544421376443321122000"},"ep12_099":{"who":"TAKUTO","text":"Then we close it. All of us. Without anyone in a chair.","mono":false,"off":364.8047,"dur":3.243,"env":"00355652121897863345410004689966423211332100000001452588751014666544444434312432544311000000000000"},"ep12_100":{"who":"SABLE","text":"Oh, I love him. Lucien, isn't he wonderful? He believes it.","mono":false,"off":368.4473,"dur":4.331,"env":"0001899976323542333575310011211110000000012354246753232212453222232333322210011210000012112333332224522100111000000000000000000000"},"ep12_101":{"who":"TAKUTO","text":"Sable. You brought me here.","mono":false,"off":373.178,"dur":1.515,"env":"0123588752665322442158995134321232211000000000"},"ep12_102":{"who":"SABLE","text":"And you came all the way down the stairs. Like a good key. Now, be a dear. Strike the wall.","mono":false,"off":375.0927,"dur":5.696,"env":"011399783123668542245642442354332234554458842433222222453210013321121233310111332323210000000000000135896652233431244332211000157842565310023323333221210000000000000000000"},"ep12_103":{"who":"RIN","text":"He wants you to break it. Why does he want you to break it?","mono":false,"off":381.1887,"dur":2.923,"env":"0067569998524426627412888750114431021001368887474437556663145244116655410133210110000000"},"ep12_104":{"who":"SABLE","text":"Ask the Saint what the wall is holding shut, thread girl. Ask him what is on the other side of the oldest scar in the sky.","mono":false,"off":384.5113,"dur":7.253,"env":"00029986420145754544320011102321344434232232123321233323433332100100000000134311002322111110000000000000015776453124321222433544453433333232354322332211012101333212224334212432221111222333112221121100000000000000000000"},"ep12_105":{"who":"LUCIEN","text":"...Sable. You said it was the Rift. Only the Rift.","mono":false,"off":392.1647,"dur":2.752,"env":"12234398774365432465334984522553047544887531010100000599777767526554587642101001000"},"ep12_106":{"who":"SABLE","text":"It is a Rift, Lucien. To the place I came from. I have been knocking on it for three hundred years. You have been holding the door shut. I am so grateful for your patience.","mono":false,"off":395.3167,"dur":10.048,"env":""},"ep12_107":{"who":"AKURO","text":"There it is, boy. That is what I fought in the sky. That is what is behind the door. Do not let him through.","mono":true,"off":405.7647,"dur":7.168,"env":"002289657655321248967743221125778988676631124555421146632256766766321112567874213445643344322455444321111000000000135775236643223787757732114532224656555543226654543221100001246666666631245431344210111456632211000000"},"ep12_108":{"who":"SABLE","text":"Then I will open it the rude way.","mono":false,"off":413.3327,"dur":2.731,"env":"0001298777754442334432143332113772132223344221123433322210000000000000000000000000"},"ep12_109":{"who":"RIN","text":"Red Thread! Hold him! Hold him still!","mono":false,"off":416.4633,"dur":2.048,"env":"02899510125988852211487762266553113776236653440465422110000000"},"ep12_110":{"who":"RIN","text":"Got you. Thin threads, but a lot of them.","mono":false,"off":418.9113,"dur":2.197,"env":"048887404457775120079998211497666325106566667666453104333210000000"},"ep12_111":{"who":"SABLE","text":"Clever girl. Your brother was clever too. Before.","mono":false,"off":421.5087,"dur":3.584,"env":"000122796455223344433321013321256642432135751123321221267433332221000002211013333221000000000000000000000000"},"ep12_112":{"who":"RIN","text":"...Before what?","mono":false,"off":425.4927,"dur":0.96,"env":"04594114888745765320022100000"},"ep12_113":{"who":"SABLE","text":"Before he went into my Rift after a little monster I let out for him. He was very brave about it.","mono":false,"off":426.8527,"dur":5.803,"env":"0000553478768457863344453243443224743111011014431112333433445544532698311121222333223333310011121012233100000000000024566414566542102555332121232211111002110000000000000000000"},"ep12_114":{"who":"RIN","text":"Then I will hold you twice as hard.","mono":false,"off":433.0553,"dur":1.941,"env":"04998989969842699972355032158766434254421145543322110000000"},"ep12_115":{"who":"LUCIEN","text":"Sanctum. Close.","mono":false,"off":435.3967,"dur":1.301,"env":"0132997664005765541133887764422211100000"},"ep12_116":{"who":"TAKUTO","text":"Break.","mono":false,"off":437.098,"dur":0.683,"env":"004799876420011000000"},"ep12_117":{"who":"LUCIEN","text":"Nothing breaks it. NOTHING.","mono":false,"off":438.1807,"dur":1.749,"env":"04789852057665328876303435652010025787520265322110000"},"ep12_118":{"who":"AKURO","text":"Boy. Let me. Just this once more. I can break it. You know I can.","mono":true,"off":440.33,"dur":4.629,"env":"0125798898775445688524867776311347864321596343125677653323655555555441102577512457762356976531254321000136888887534564201125554443211100000"},"ep12_119":{"who":"TAKUTO","text":"No. This time it is me. Only me.","mono":false,"off":445.3593,"dur":2.24,"env":"02468986521286440236654442443213332110000004665444443332100000000000"},"ep12_120":{"who":"AKURO","text":"...Then do not miss.","mono":true,"off":447.9993,"dur":1.344,"env":"01333997866444666767851124554311122211000"},"ep12_121":{"who":"TAKUTO","text":"Haruki.","mono":false,"off":449.7433,"dur":0.939,"env":"00148997874021455321110000000"},"ep12_122":{"who":"HARUKI","text":"I know. Rin, the gap. Tie it open.","mono":false,"off":451.082,"dur":2.176,"env":"018999997777775558887775754587763000537877777541578620332222100000"},"ep12_123":{"who":"RIN","text":"One gap. Two seconds. Go!","mono":false,"off":453.658,"dur":1.707,"env":"0489999588764000235763336630155532016876543321000000"},"ep12_124":{"who":"LUCIEN","text":"Haruki, don't!","mono":false,"off":455.7647,"dur":1.365,"env":"01259988678873012576544222897653302221000"},"ep12_125":{"who":"HARUKI","text":"You caught me once. Let me catch you.","mono":false,"off":457.53,"dur":1.92,"env":"0489514698536765566665433214773466311687533314432222100000"},"ep12_126":{"who":"HARUKI","text":"Frozen Hour.","mono":false,"off":459.85,"dur":1.259,"env":"00117976666558665466676454433333200000"},"ep12_127":{"who":"HARUKI","text":"Three.","mono":false,"off":461.5087,"dur":0.683,"env":"003338999877666431000"},"ep12_128":{"who":"HARUKI","text":"Two.","mono":false,"off":462.5913,"dur":0.601,"env":"0223697766653321000"},"ep12_129":{"who":"HARUKI","text":"One. Takuto!","mono":false,"off":463.592,"dur":1.344,"env":"04798887762489852298444987664444443200000"},"ep12_130":{"who":"TAKUTO","text":"RUINBREAKER!","mono":false,"off":465.336,"dur":0.981,"env":"013688877647986202553210000000"},"ep12_131":{"who":"RIN","text":"The light. It is going back. Out of the walls. Into people.","mono":false,"off":466.7173,"dur":3.029,"env":"0377877775103000699758744049876764465532001015674216545676544332310465233001354002321000000"},"ep12_132":{"who":"HARUKI","text":"The beds. The crystal beds are cracking open.","mono":false,"off":470.1467,"dur":2.453,"env":"03986597766554420463239854047755377665446531226877412665457752133221110000"},"ep12_133":{"who":"LUCIEN","text":"...It broke. Twelve years. And it broke.","mono":false,"off":473.0,"dur":2.048,"env":"01598210699877401103279775334686655434355653103787764310210000"},"ep12_134":{"who":"HARUKI","text":"It was always going to, Lucien. Everything breaks. That is why you need people, not walls.","mono":false,"off":475.448,"dur":4.779,"env":"187995339886588865227976666523387556777433465300497368724766526986420134331000000000005996875447876657776766411167510444457752246765432113321000"},"ep12_135":{"who":"LUCIEN","text":"Haruki. When you fell. I did catch you. That part was real.","mono":false,"off":480.6267,"dur":3.52,"env":"0015988789840126655556677631159764431000000006763597320237755124224442211776100158751154423467765432210000"},"ep12_136":{"who":"HARUKI","text":"I know. That is why it hurt so much.","mono":false,"off":484.5467,"dur":2.112,"env":"1799998987877655387757765589777534399731444587766543220232100000"},"ep12_137":{"who":"SABLE","text":"Bravo. Bravo! Oh, Ruinbreaker. You opened my door at last.","mono":false,"off":487.0587,"dur":4.309,"env":"0000168967633443201345554311222110023543422344533421232101112110000012334521245533332233333211232222125898512100000000000000000000"},"ep12_138":{"who":"SABLE","text":"The oldest scar in the sky is open. And it goes to so many places.","mono":false,"off":491.768,"dur":4.779,"env":"001185498874478677774378987655545466324664532232322454210133432000000000026864214899854323357646564665211244442332232111110000000000000000000000"},"ep12_139":{"who":"SABLE","text":"Goodbye for now, Takuto. Give my regards to the cat.","mono":false,"off":496.9467,"dur":4.267,"env":"00017942499997511235544443234321332444111223245222221210000000154226565533421223333337633211111123211012210000000000000000000000"},"ep12_140":{"who":"TAKUTO","text":"SABLE!","mono":false,"off":501.6133,"dur":0.747,"env":"00237999737865321000000"},"ep12_141":{"who":"HARUKI","text":"Takuto. Look at the crack. Look what is on the other side.","mono":false,"off":502.76,"dur":3.051,"env":"12997411986237887655577317426312497764210000000038841157857654766666665465443275443222110000"},"ep12_142":{"who":"TAKUTO","text":"That is... that is the crossing. In Nerima. That is our crossing.","mono":false,"off":506.2107,"dur":3.733,"env":"0366367998642200156546320320116776423323221013454455665334445442211000000000466353354410115664323211000000000000"},"ep12_143":{"who":"WICK","text":"We got them out. All of them. Every chair. I... what is that? Is that... is that Japan?","mono":false,"off":510.344,"dur":4.331,"env":"0562999700878877740048887863387730377347841442787665324665454200036968965308866400344521765431010000455167631236212543211100000000"},"ep12_144":{"who":"HARUKI","text":"It is closing. Slowly. A minute. Maybe two.","mono":false,"off":515.0747,"dur":2.432,"env":"0597785411259777655655433322688766456544567766511466653652323764321110000"},"ep12_145":{"who":"WICK","text":"Osaka is down there. Somewhere. Four tables. My mom.","mono":false,"off":517.9067,"dur":3.093,"env":"068644797201787675310776666654443233576665433320000078731358773255331455555555432211100000000"},"ep12_146":{"who":"NEMU","text":"You should go, Wick.","mono":false,"off":521.4,"dur":1.237,"env":"00286556320599987543210006753100110000"},"ep12_147":{"who":"WICK","text":"...Three years, I wanted this. Every single night. Corn soup. Vending machines. My mom yelling at me to flip the pancakes.","mono":false,"off":523.0373,"dur":6.72,"env":"0001477666456788854359874589665216543332100488237744436654766656432100000002177777544437753001000002298775767663332665433232310000047667678889966657776655552145525201374000412365542114321002322000000000"},"ep12_148":{"who":"WICK","text":"And now it is right there. And all I can think about is that nobody here can make okonomiyaki but me.","mono":false,"off":530.1573,"dur":5.461,"env":"07998887778863485977633998861001753222100000000058999988884158711776276288763235743852257888884487565322676301576763110388401777766666555663012522531232111000000000"},"ep12_149":{"who":"NEMU","text":"That is true. We would starve.","mono":false,"off":536.0187,"dur":1.92,"env":"0157726644124118985310000000000386561432476543321111000000"},"ep12_150":{"who":"WICK","text":"I have friends here, Nemu. That is the first time in three years I could say that. I am not leaving my first friends to go look for a pancake.","mono":false,"off":538.3387,"dur":7.488,"env":"066645882111497677452167876667666666542222100000006994676515610089854203477766666620114766445655643344520154145366553344330000000003677788899962248883676776651004876431105654543412342576544740010055302465541123210000000000000"},"ep12_151":{"who":"HARUKI","text":"Takuto. You came here for me. I am here. The road home is right there.","mono":false,"off":546.2267,"dur":3.627,"env":"1289721285247655545412755543666311555444420005666555542266653210000465577755553665555443257654200343221100000"},"ep12_152":{"who":"TAKUTO","text":"What about you?","mono":false,"off":550.2533,"dur":0.981,"env":"003766398873023245421111000000"},"ep12_153":{"who":"HARUKI","text":"Forty people in crystal are waking up and do not know where they are. I put some of them in those beds. I am staying until they are home.","mono":false,"off":551.6347,"dur":7.019,"env":"0017999576302287303656664122875403753257754666521166545651025755766767513676665446677636654334421100000000000587215932546666445666666655530078753222432000000000028887665442177766655554325754665565424764311100000"},"ep12_154":{"who":"TAKUTO","text":"...Then I am staying too.","mono":false,"off":559.0533,"dur":1.451,"env":"00277798777644304955545412316763211000000000"},"ep12_155":{"who":"HARUKI","text":"Takuto. Your mother.","mono":false,"off":560.904,"dur":1.536,"env":"03498741277634387665554466566665243333222100000"},"ep12_156":{"who":"TAKUTO","text":"My mother has your mother. They put posters on poles together. They will be fine for a little while longer.","mono":false,"off":562.84,"dur":6.208,"env":"0255665678547633346544324344554211100000000004411295000214764352024323333443111055433233022124430210000000000004654621442111175556543332111133432234344422343433223444433211110000000000000"},"ep12_157":{"who":"TAKUTO","text":"Sable is loose. The scar is open. And there is a cat at the crossing who needs somebody to feed it coffee milk.","mono":false,"off":569.448,"dur":6.933,"env":"0012498882576576322337985321122210000000003454301777787654443323564002210000000000000146666677535401113566646202300116765422223333244444444312332454443444333201210003342420001135541013333433110000000000000000"},"ep12_158":{"who":"TAKUTO","text":"I am not going home to feed the cat while the man who brought me here walks around. I am going to find him. And break him.","mono":false,"off":576.7813,"dur":7.403,"env":"0002556665556666311159865433321455443313221112333211301112444321001234224344334444433311155652023320023333224552014432233343210000000000000000000025555555327975442421114544444311210000000023321465430011110000000000000000000"},"ep12_159":{"who":"RIN","text":"...You are staying.","mono":false,"off":584.584,"dur":1.003,"env":"0368999533317777654434310000000"},"ep12_160":{"who":"TAKUTO","text":"I still have your brother's scarf on my wrist. I have to give it back with me attached.","mono":false,"off":585.9867,"dur":4.864,"env":"00354330197654456513442146662443333330035566541103333333322365421122000000000000002455566210241166264104554420023003333201113432100012200000000000"},"ep12_161":{"who":"RIN","text":"Idiot.","mono":false,"off":591.2507,"dur":0.661,"env":"07947889973012100000"},"ep12_162":{"who":"NEMU","text":"You will go back someday. When you are done breaking things here.","mono":false,"off":592.312,"dur":3.712,"env":"0014256156871176530034344554424211100000000000000000000000028999777400599998763456630355530027766434413211110000"},"ep12_163":{"who":"TAKUTO","text":"Someday.","mono":false,"off":596.424,"dur":0.811,"env":"0012797664787542110000000"},"ep12_164":{"who":"WICK","text":"Takuto. If you ever get back there. Buy two corn soups from a machine. Drink one for me.","mono":false,"off":597.6347,"dur":4.779,"env":"016994016624487766423511578845642773004776300024332221000465520526875202166666544365213135655543334554332210000014653103555541124332111100000000"},"ep12_165":{"who":"TAKUTO","text":"We will get back. Both of us. And I will buy three.","mono":false,"off":602.8133,"dur":3.072,"env":"024445228930057654200005776311431232112332100000003454456553355221544443111123332100000000000"},"ep12_166":{"who":"WICK","text":"Three? Who is the third one for?","mono":false,"off":606.2853,"dur":1.557,"env":"01379987768988633830039999546755113554422100000"},"ep12_167":{"who":"TAKUTO","text":"Coffee.","mono":false,"off":608.2427,"dur":0.747,"env":"01379983112654321100000"},"ep12_168":{"who":"WICK","text":"...The cat. You are buying corn soup for the cat. That is a terrible thing to give a cat.","mono":false,"off":609.3893,"dur":4.245,"env":"01681124888751013588984279776666741216766675543630116342115644210000000026867655514257778536651005555523325424111543210100000000"},"ep12_169":{"who":"TAKUTO","text":"Goodbye, Nerima. Not yet.","mono":false,"off":614.0347,"dur":1.835,"env":"14621798755455555323444443321100013454200145310001000000"},"ep12_170":{"who":"CROWD","text":"My mark! My mark came back!","mono":false,"off":616.2693,"dur":2.091,"env":"035677888888996410002444455655420012344442043321100000000000000"},"ep12_171":{"who":"CROWD2","text":"Mama, I am warm again. I am warm!","mono":false,"off":618.76,"dur":2.261,"env":"02498886666534655443324553442144432210027655433234444332110000000000"},"ep12_172":{"who":"HARUKI","text":"Mira. Mira, it is me. Haruki.","mono":false,"off":621.4213,"dur":2.091,"env":"048997766765556666667633546554466554422498666663022442211100000"},"ep12_173":{"who":"CROWD2","text":"Haruki? Is this... is this Osaka?","mono":false,"off":623.912,"dur":2.453,"env":"00169975665300144432332102544211110011354211453211454321256410144433110000"},"ep12_174":{"who":"HARUKI","text":"...No. Not yet. But I am going to take you there. I promise. A real promise this time.","mono":false,"off":626.7653,"dur":4.352,"env":"07998776777652377641007577776664866544141864115753654442004784011877754212433100000000787578787630117776565530265430347543221100000"},"ep12_175":{"who":"VESPER","text":"Lucien Aurel. By the authority of the Hunters' Guild, you are under arrest. I have a letter. I wrote it myself.","mono":false,"off":631.5173,"dur":6.059,"env":"03799544379720488875553331000005674356640001777777355651044213664223432101543333111026555555552444443466422122201100000000567436617667653332220000015663376522312444322215432210000000"},"ep12_176":{"who":"LUCIEN","text":"...Takuto. The scar will open again. Without a wall, the sky will come for this city.","mono":false,"off":637.976,"dur":4.885,"env":"000238864023973034887654321004434028766676466467830165542166553221000000000387697658643677786544313334217655555436310347655113532533333277423210000"},"ep12_177":{"who":"TAKUTO","text":"Then we will be on the wall. Standing. Not sitting in chairs.","mono":false,"off":643.2613,"dur":3.499,"env":"003556765841467766555432589996321100000023118666653432111000035773024337734444431343454432110012100000000"},"ep12_178":{"who":"LUCIEN","text":"...I hope you are right. For their sake. I truly do.","mono":false,"off":647.16,"dur":2.709,"env":"0148876689511588865587664200015736775444387641000002565124339986465313777532210000"},"ep12_179":{"who":"KUROZANE","text":"Valen. The Saint is broken. The suit is gone. We are both still standing.","mono":false,"off":650.2693,"dur":4.693,"env":"001288998666554421331111654423321000466530002221110000311124552033210025665543222110002344311366431001001422111013222221111110000000000000000"},"ep12_180":{"who":"SIEG","text":"So, our duel?","mono":false,"off":655.3627,"dur":1.216,"env":"0337987676521578875499887754444210000"},"ep12_181":{"who":"KUROZANE","text":"...Another day. I find I am enjoying waiting for it.","mono":false,"off":656.9787,"dur":3.477,"env":"001266789829731487554210000034410017765545654433333332122555433332224444222220000222111100000000000000000"},"ep12_182":{"who":"SIEG","text":"Patience is a very scary bear, Kurozane.","mono":false,"off":660.856,"dur":2.901,"env":"0797654367654222000586776656755456533300565556664266554443100000016976666447554432210000"},"ep12_183":{"who":"KUROZANE","text":"What?","mono":false,"off":664.1573,"dur":0.683,"env":"013469999875310000000"},"ep12_184":{"who":"SIEG","text":"Ha ha ha! I will tell you the joke someday. You will hate it.","mono":false,"off":665.24,"dur":3.861,"env":"00486666456555652665555553000001687676513286555665465434786631243357666645444431000000000599776664497773224320121000"},"ep12_185":{"who":"CLERK","text":"Welcome back, Hunters! All nine of you! Ten, counting Tofu! Eleven, counting the hat!","mono":false,"off":669.5013,"dur":4.437,"env":"04995004977499762001476411666623105878776766777672235542002026666443011366641355401057731004554215435674265330111455411444332123220000"},"ep12_186":{"who":"GIDEON","text":"The hat is not a member.","mono":false,"off":674.3387,"dur":1.664,"env":"02633338975210010000034332767655344444443321110000"},"ep12_187":{"who":"WICK","text":"The hat has been through a LOT, Gideon.","mono":false,"off":676.4027,"dur":2.091,"env":"044479856785307874115789952687688630533655421484443221110000000"},"ep12_188":{"who":"VALENTINE","text":"Tofu has been begging to read Takuto again. He thinks he can finally do it.","mono":false,"off":678.8933,"dur":4.48,"env":"023899311376335854204656514774144441313225444200321378400134132345453112322222000000000000550486324342135520018777754333203443220021000"},"ep12_189":{"who":"VALENTINE","text":"Ruinbreaker. Rank...","mono":false,"off":683.7733,"dur":1.6,"env":"024898787874256663011333221125764321011000000000"},"ep12_190":{"who":"VALENTINE","text":"Error. With a little crown. He drew the crown himself.","mono":false,"off":685.7733,"dur":2.944,"env":"07999999865424815866657202248765544443000000000683669961902248877663556467557643201100000"},"ep12_191":{"who":"TAKUTO","text":"Still an error.","mono":false,"off":689.1173,"dur":0.981,"env":"012049766531467655321110000000"},"ep12_192":{"who":"VALENTINE","text":"The best kind, darling. The kind that breaks the rules.","mono":false,"off":690.4987,"dur":2.923,"env":"0541896253211146665555224554333333320000014022687785620056411320242256643222112200000000"},"ep12_193":{"who":"CLERK","text":"Also, the Guild has promoted you. All of you. Rank F to rank C!","mono":false,"off":693.8213,"dur":3.563,"env":"06752229987447206987447620014667788574114543321000049998783367765311266665211276300124355443111223433221000"},"ep12_194":{"who":"WICK","text":"RANK C! Mom! I am rank C! I skipped two ranks!","mono":false,"off":697.784,"dur":2.496,"env":"069884436788899897566777777876623335664336663321960003296466441111221000000"},"ep12_195":{"who":"NEMU","text":"Does rank C get more bread?","mono":false,"off":700.68,"dur":1.685,"env":"023453069998412222246530235200376653023432211010000"},"ep12_196":{"who":"CLERK","text":"Rank C gets slightly more bread.","mono":false,"off":702.7653,"dur":1.451,"env":"04887412682892121388647767763147654433110000"},"ep12_197":{"who":"NEMU","text":"Then it is worth it.","mono":false,"off":704.616,"dur":1.323,"env":"0179997653101862545410255541101210002000"},"ep12_198":{"who":"SIEG","text":"One. Two. Three. Four. Five. Six. Seven. Eight. Nine. Ten.","mono":false,"off":706.3387,"dur":3.883,"env":"078766642288666411377666410067666553105855556423227631232013227764665311587421100000000289766666655300229864322210000"},"ep12_199":{"who":"TAKUTO","text":"You are counting.","mono":false,"off":710.6213,"dur":1.067,"env":"01469940227988761445322111000000"},"ep12_200":{"who":"SIEG","text":"Ten. Everyone is here. And I am going to count it every night, out loud, until you are all sick of it.","mono":false,"off":712.088,"dur":6.208,"env":"0239655544420004654676555554455433116653222000000000000377755544444545545424102564454274100255436656554445412100000366510156655444434320000000002663487666555422454433322363005323210210000"},"ep12_201":{"who":"RIN","text":"Takuto. The scarf.","mono":false,"off":718.696,"dur":1.365,"env":"02797217942599986365442187664431011000000"},"ep12_202":{"who":"TAKUTO","text":"With me attached. Like I said.","mono":false,"off":720.4613,"dur":1.707,"env":"0373268899303699974132025552155653324643210000000000"},"ep12_203":{"who":"RIN","text":"...Keep it.","mono":false,"off":722.568,"dur":0.768,"env":"021179982079764111100000"},"ep12_204":{"who":"TAKUTO","text":"You said it stays the way he wore it.","mono":false,"off":723.736,"dur":2.005,"env":"0134333993621320565542104323444331033322456565321100000000000"},"ep12_205":{"who":"RIN","text":"He would have liked it on you. Do not make a thing of it.","mono":false,"off":726.1413,"dur":2.667,"env":"00554797712677630035365655554443332000036766665125421320015444441032210221000000"},"ep12_206":{"who":"VESPER","text":"Error. A word.","mono":false,"off":729.208,"dur":1.365,"env":"00178997777675207853498775433332012320000"},"ep12_207":{"who":"TAKUTO","text":"Vesper.","mono":false,"off":730.9733,"dur":0.747,"env":"00179854200776431100000"},"ep12_208":{"who":"VESPER","text":"The Guild asked me for a report on you. I wrote one page. It is very boring. Nothing about it is red.","mono":false,"off":732.12,"dur":5.803,"env":"0421898633126564332026530125555345100027532234444333321000005664378762002466653012433222101211000000053474320376555410066555443332210056852004555520544311213332114543222010000"},"ep12_209":{"who":"TAKUTO","text":"Thank you.","mono":false,"off":738.3227,"dur":0.832,"env":"0019987611168754321100000"},"ep12_210":{"who":"VESPER","text":"Keep it boring. I would like to read more boring reports about you for a very long time.","mono":false,"off":739.5547,"dur":4.757,"env":"02278301750000069788655332220000000574624961033532555531287666520056665554444000056411323155432023233211135552117654443555554431314433221111000"},"ep12_211":{"who":"AKURO","text":"You know, boy. Three hundred years in an axe, and these are the loudest people I have ever met.","mono":true,"off":744.712,"dur":6.379,"env":"013458887876886621148889888676531000001235564553225898648963223555567654334555442135666532101343213465324555656654323464464334466776632444332000122231023433211234444421233223433223332100011000"},"ep12_212":{"who":"TAKUTO","text":"You like them.","mono":false,"off":751.4907,"dur":0.981,"env":"013654899873010564322110000000"},"ep12_213":{"who":"AKURO","text":"...Ask me again in another three hundred years.","mono":true,"off":752.872,"dur":2.816,"env":"0022257876333114878852478865444345556797556431001244676355643454212346654321112221100"},"ep12_214":{"who":"TAKUTO","text":"Ashford rebuilt the forge. Gideon made the new door fight the old one, just to see who would win.","mono":false,"off":756.088,"dur":6.208,"env":"0005789745311377732257321688620013111156543210001220000000000000159476776666666662165555665315656651111776431001333356653112322211100003554510333443243332134323422224555310000000000000000"},"ep12_215":{"who":"TAKUTO","text":"In Marrowmere, the little girl who saw the sad head got a job at the Guild. She is the youngest cousin.","mono":false,"off":762.696,"dur":6.187,"env":"001677677878889987555544431443485773124777664334333346552244432655553111454421113443321133355565631310121027765211000000000000000000245346864302532256555435341001146532211000000000000000"},"ep12_216":{"who":"TAKUTO","text":"Fort Cinder put thirty-one names on a stone. Giant names. Commander Hale made them up himself.","mono":false,"off":769.2827,"dur":6.229,"env":"0003896113436536510153000057753543245433333333333332233322332035444321100100000000003566544321134444321100012100000000000001545555535522246554433333421333331013222332455310000000000000000"},"ep12_217":{"who":"TAKUTO","text":"The Plume Ogres sent a feather to every village in the Greatwood. Nobody has been raided since.","mono":false,"off":775.912,"dur":5.909,"env":"0510111598876432579952134333234433443341110068724431223003441134321265434331133333320135553100111000000000000000034679982297634333345431013344332344554232013322110001221000000000"},"ep12_218":{"who":"TAKUTO","text":"There are forty graves at the pass shrine. Kurozane cleans them every morning. He says it is for practice.","mono":false,"off":782.2213,"dur":6.72,"env":"0005789972111058984732113666654433212242012012234454334322034554421110100000000000001117888853475554302005555553212544203542244455556543221111000000143334764234334433310320013575300002100122100000000000"},"ep12_219":{"who":"TAKUTO","text":"And in Saint Lumen, forty people who slept in crystal are learning how to buy bread. Haruki is teaching them.","mono":false,"off":789.3413,"dur":7.104,"env":"0025677643433766422356544443332000000015898565302144301543333244314551002333101157343013333103333234444444333223443333214444332113565531100000000000000000015998756653011033223222200213310242322211110000000000000000"},"ep12_220":{"who":"CROWD","text":"What is that smell?","mono":false,"off":796.8453,"dur":1.579,"env":"025797589742157654002333156654322111100000000000"},"ep12_221":{"who":"CROWD2","text":"It smells like a pancake had an argument with a cabbage.","mono":false,"off":798.824,"dur":3.008,"env":"0991333267888876317731510135544212444310012746433478752134343223143013677223211222100000000"},"ep12_222":{"who":"WICK","text":"Welcome! Welcome to Four Tables! The only okonomiyaki in this entire world!","mono":false,"off":802.232,"dur":4.608,"env":"0389850138766543888402666344511147775143566531322123320000000651268776766217873027666665655566520034445544424441315655554234322111000000000"},"ep12_223":{"who":"TAKUTO","text":"You opened a shop.","mono":false,"off":807.24,"dur":1.152,"env":"01354589215455333236554211000000000"},"ep12_224":{"who":"WICK","text":"A stall. Gideon built it. It only caught fire once. Okay, twice.","mono":false,"off":808.792,"dur":3.755,"env":"04443199999874328957778851887612265300037577777731279510018876665444333223221000000377311575522216642212321000000"},"ep12_225":{"who":"NEMU","text":"There is only one table.","mono":false,"off":812.9467,"dur":1.472,"env":"011444443105987654421001354430311212020000000"},"ep12_226":{"who":"WICK","text":"It is called Four Tables because of my mom's shop. This is the first table. I will get the other three.","mono":false,"off":814.8187,"dur":5.504,"env":"1868955102299884210047787123577743565320053157455367665777666665553233258754100000000000069644465407410288743202155552233321002665564237510455445420114543211100000000"},"ep12_227":{"who":"RIN","text":"And when you get all four?","mono":false,"off":820.7227,"dur":1.344,"env":"05766999886229745665532221654432110000000"},"ep12_228":{"who":"WICK","text":"Then I will have her shop. Here. Until I can go back and tell her about it.","mono":false,"off":822.4667,"dur":3.627,"env":"0487878769656883158644458787510001116765432000000058574978875118859842886621564452766456653454432321020000000"},"ep12_229":{"who":"TAKUTO","text":"Two please. No. Three.","mono":false,"off":826.4933,"dur":1.536,"env":"04497202399876643356799852111135754210100000000"},"ep12_230":{"who":"WICK","text":"Three? Who is the third...","mono":false,"off":828.4293,"dur":1.301,"env":"0147898877898864167200798764431211000000"},"ep12_231":{"who":"NEMU","text":"Me. Both of the extra ones are me.","mono":false,"off":830.1307,"dur":2.411,"env":"0279964100000000000598751200134115400385023313443234544353234333210000000"},"ep12_232":{"who":"WICK","text":"...Coming right up. Takoyaki, left hand. Very gently.","mono":false,"off":832.9413,"dur":2.859,"env":"01687877698877984005387213977778630145445764103156555553114866654244665311221110000000"},"ep12_233":{"who":"NEMU","text":"This is where I first died in front of you.","mono":false,"off":836.2,"dur":2.261,"env":"03622120029541045443442000055523200036544433221323100045442001000000"},"ep12_234":{"who":"TAKUTO","text":"You say it like it is a nice memory.","mono":false,"off":838.8613,"dur":2.24,"env":"01333335987952365410144100242234444445554422103454533211100000000000"},"ep12_235":{"who":"NEMU","text":"It is. It is where I met you. The dying part was only a little bit of it.","mono":false,"off":841.5013,"dur":5.504,"env":"0164103996421112221000000000000000003824644104555434554443200221110000000000000000000000000000015046757776554122132221001000055430498766654343234243134414111110010000"},"ep12_236":{"who":"NEMU","text":"Do you remember what the axe asked you? Here. That night.","mono":false,"off":847.4053,"dur":3.691,"env":"021364677777663653253024412764203323442332041211100000000000000000000169964311000000000000155310255332110012000"},"ep12_237":{"who":"TAKUTO","text":"What is it you want to break.","mono":false,"off":851.496,"dur":1.579,"env":"003797898445861012344456555431257542100000000000"},"ep12_238":{"who":"NEMU","text":"And? What do you want to break? Now?","mono":false,"off":853.4747,"dur":2.389,"env":"002898520077242368646662332044565310002100000000000000027876543211100000"},"ep12_239":{"who":"TAKUTO","text":"...Sable. Someday. The scar in the sky. The idea that somebody has to sit in a chair so everybody else can be safe.","mono":false,"off":856.264,"dur":7.744,"env":"00122688993377542000222787665242111100000000244331047778776324444322210145654311000000000000000002586765522145589951552012226544354343334442001322214642344310232144443332223330024412442144443332233321101332211111443100000000000000000"},"ep12_240":{"who":"TAKUTO","text":"But today? Nothing. Not today.","mono":false,"off":864.408,"dur":1.941,"env":"04204352699875321000145784113333333454103322432110000000000"},"ep12_241":{"who":"NEMU","text":"Good. Today is for sleeping.","mono":false,"off":866.7493,"dur":1.92,"env":"2299875310000003383998755431000047341033453144410321100000"},"ep12_242":{"who":"SABLE","text":"Hello, kitty. Waiting for someone?","mono":false,"off":869.0693,"dur":2.752,"env":"00113699789966311113422322110134543334531114887332222222210000000000000000000000000"},"ep12_243":{"who":"SABLE","text":"He is not coming tonight. But I am sure he will. Everyone always comes.","mono":false,"off":872.2213,"dur":4.779,"env":"000048886599963111234453331222332232100000002334444434565332321123123332222100000001443122323332223222235411122222211343210000000000000000000000"}}};
